            if (idx >= static_cast<std::size_t>(kNilIndex))
                throw std::length_error("TreeNodePoolStore: index_type-Kapazitaet erschoepft (#234-F3)");
            nodes_.push_back(node_type{k, v, kNilIndex, kNilIndex});
        }
        ++size_;
